package com.bank.balance.service;

import java.util.logging.Logger;

// Finds the minimum achievable difference when splitting into two subsets.
public class BalancedSplitService {
    private static final Logger log = Logger.getLogger(BalancedSplitService.class.getName());

    public int minDifference(int[] amounts) {
        int total = 0;
        for (int a : amounts) total += a;
        int target = total / 2;                      // aim for closest to half
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;
        for (int num : amounts) {
            for (int t = target; t >= num; t--) {    // high → low ⇒ each item once
                dp[t] = dp[t] || dp[t - num];
            }
        }
        int best = 0;
        for (int s = target; s >= 0; s--) {          // largest reachable sum ≤ half
            if (dp[s]) { best = s; break; }
        }
        int diff = total - 2 * best;                 // gap between the two subsets
        log.info(() -> "Minimum subset sum difference = " + diff);
        return diff;
    }
}
