package com.bank.balance;

import com.bank.balance.service.BalancedSplitService;
import java.util.logging.Logger;

public class BalancedSplitApplication {
    private static final Logger log = Logger.getLogger(BalancedSplitApplication.class.getName());

    public static void main(String[] args) {
        BalancedSplitService service = new BalancedSplitService();
        int[] payouts = {11, 6, 5, 3};       // payout amounts (in thousands)
        int diff = service.minDifference(payouts);
        log.info("Smallest workload difference between tellers: " + diff);
    }
}
